insert into public.biblical_verse_texts(source_id,book_code,chapter,verse,language,original_text,normalized_text,transliteration,literal_translation_es,text_direction,token_count,analysis_status,source_locator,provider_version,content_hash,review_status,enabled,approved_at,metadata)
select source.id,d.b,d.c,d.v,d.l,d.o,d.n,d.t,d.e,d.d,d.cnt,d.a,
 (case when d.b='PSA' then 'https://github.com/STEPBible/STEPBible-Data/blob/b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39/Translators%20Amalgamated%20OT%2BNT/TAHOT%20Job-Sng%20-%20Translators%20Amalgamated%20Hebrew%20OT%20-%20STEPBible.org%20CC%20BY.txt' else 'https://github.com/STEPBible/STEPBible-Data/blob/b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39/Translators%20Amalgamated%20OT%2BNT/TAGNT%20Mat-Jhn%20-%20Translators%20Amalgamated%20Greek%20NT%20-%20STEPBible.org%20CC-BY.txt' end)||'#L'||(d.ln->>0)||'-L'||(d.ln->>1),
 'STEPBible-Data@b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39',encode(extensions.digest(concat_ws('|',d.b,d.c::text,d.v::text,d.l,d.o,d.n,d.t,d.e,d.cnt::text,d.bp,'b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39'),'sha256'),'hex'),
 'approved',true,now(),jsonb_build_object('source_commit','b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39','source_file_hash',d.fh,'source_excerpt_hash',d.eh,'source_lines',d.ln,'base_text_policy',d.bp,'translation_kind','editorial_literal','generated_by_ai',false,'review_level','source_validated')
from data d cross join source
on conflict(source_id,book_code,chapter,verse,language) do update set original_text=excluded.original_text,normalized_text=excluded.normalized_text,transliteration=excluded.transliteration,literal_translation_es=excluded.literal_translation_es,text_direction=excluded.text_direction,token_count=excluded.token_count,analysis_status=excluded.analysis_status,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,approved_at=coalesce(public.biblical_verse_texts.approved_at,excluded.approved_at),metadata=excluded.metadata,updated_at=now();

