insert into public.biblical_textual_variants(source_id,verse_text_id,variant_key,anchor_word_index,reading_type,base_reading,variant_reading,witness_summary,witnesses,editions,significance_es,source_locator,provider_version,content_hash,review_status,enabled,approved_at,metadata)
select source.id,vt.id,d.k,d.w,d.t,d.br,d.vr,d.ws,d.wi,d.ed,d.sg,'https://github.com/STEPBible/STEPBible-Data/blob/b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39/Translators%20Amalgamated%20OT%2BNT/TAGNT%20Mat-Jhn%20-%20Translators%20Amalgamated%20Greek%20NT%20-%20STEPBible.org%20CC-BY.txt#L'||d.ln,'STEPBible-Data@b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39',
 encode(extensions.digest(concat_ws('|',d.k,d.w::text,d.t,coalesce(d.br,''),coalesce(d.vr,''),d.ws,d.ed::text,d.sg,d.ln::text,'b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39'),'sha256'),'hex'),
 'approved',true,now(),jsonb_strip_nulls(jsonb_build_object('source_commit','b86d26cdb1f51729e73b5b4eb7f7ccadc5dfba39','source_file_hash','ab8eaaeb68e17a1dcfa34e1e9350358f22f03bc2a97244d848750ad81044bc8e','source_excerpt_hash','3b36d9f586fe932d4fa21065ab6fe556f2788d2b2fe0ac252b48099e21853cfa','source_reference',d.ref,'source_line',d.ln,'source_lexical_id',d.si,'display_word_index',d.dw,'modifies_source_word_index',d.mod,'generated_by_ai',false,'review_level','source_validated'))
from data d cross join source join public.biblical_verse_texts vt on vt.source_id=source.id and vt.book_code=d.b and vt.chapter=d.c and vt.verse=d.v and vt.language=d.l
on conflict(source_id,verse_text_id,variant_key) do update set anchor_word_index=excluded.anchor_word_index,reading_type=excluded.reading_type,base_reading=excluded.base_reading,variant_reading=excluded.variant_reading,witness_summary=excluded.witness_summary,witnesses=excluded.witnesses,editions=excluded.editions,significance_es=excluded.significance_es,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,approved_at=coalesce(public.biblical_textual_variants.approved_at,excluded.approved_at),metadata=excluded.metadata,updated_at=now();

do $validate$
declare s uuid;vt integer;v integer;bad integer;
begin
 select id into s from public.biblical_sources where slug='stepbible-lexical-pilot';
 select count(*) into vt from public.biblical_verse_texts where source_id=s and enabled and review_status='approved';
 select count(*) into v from public.biblical_textual_variants where source_id=s and enabled and review_status='approved';
 select count(*) into bad from (select content_hash from public.biblical_verse_texts where source_id=s and enabled union all select content_hash from public.biblical_textual_variants where source_id=s and enabled) q where content_hash is null or content_hash !~ '^[0-9a-f]{64}$';
 if vt<>2 then raise exception 'Se esperaban 2 textos; se obtuvieron %',vt; end if;
 if v<>2 then raise exception 'Se esperaban 2 variantes; se obtuvieron %',v; end if;
 if bad<>0 then raise exception 'Hashes de textos o variantes inválidos: %',bad; end if;
end $validate$;